const CFG_KEY = 'cfg', CFG_AT_KEY = 'cfgSyncedAt', CFG_SRC_KEY = 'cfgSource';
function loadConfigFromDb() {
  // 读 setting 表里的 cfg（整份 PANEL_CONFIG 的 JSON）
  let raw = null;
  try { const rows = q("SELECT v FROM setting WHERE k=?", [CFG_KEY]); raw = rows.length ? rows[0].v : null; } catch (e) { raw = null; }
  if (raw) {
    try { applyConfig(JSON.parse(raw)); return 'db'; } catch (e) { console.warn('库内配置解析失败，回退 config.js', e); }
  }
  // 库内没有 → 首次从 config.js 导入并写库（若存在）
  if (CFG_FROM_JS) {
    try {
      const now = new Date().toISOString();
      db.run('INSERT OR REPLACE INTO setting(k,v) VALUES(?,?)', [CFG_KEY, JSON.stringify(CFG_FROM_JS)]);
      db.run('INSERT OR REPLACE INTO setting(k,v) VALUES(?,?)', [CFG_AT_KEY, now]);
      db.run('INSERT OR REPLACE INTO setting(k,v) VALUES(?,?)', [CFG_SRC_KEY, '首次导入']);
      queueSave();
      applyConfig(CFG_FROM_JS);
      return 'imported';
    } catch (e) { applyConfig(CFG_FROM_JS); return 'js'; }
  }
  applyConfig(null);
